class SettingsViewModel(private val settingsStore:SettingsStore,private val backupRepository:BackupRepository):ViewModel(){val appLockType=settingsStore.appLockType;val aiFeaturesEnabled=settingsStore.aiFeaturesEnabled;private val _exportStatus=MutableStateFlow<String?>(null);val exportStatus:StateFlow<String?>=_exportStatus;private val _lastExportedFile=MutableStateFlow<java.io.File?>(null);val lastExportedFile:StateFlow<java.io.File?>=_lastExportedFile;fun setAiFeaturesEnabled(enabled:Boolean)=viewModelScope.launch{settingsStore.setAiFeaturesEnabled(enabled)};fun exportBackup(directory:java.io.File){viewModelScope.launch{runCatching{backupRepository.exportToFile(directory,"0.1.0")}.onSuccess{_lastExportedFile.value=it;_exportStatus.value="Backup exported successfully"}.onFailure{_exportStatus.value="Export failed: ${it.message}"}}}}

@Composable
fun SettingsScreen(onOpenAppLockSetup:()->Unit){val locator=LocalServiceLocator.current;val context=LocalContext.current;val vm:SettingsViewModel=viewModel(factory=LambdaViewModelFactory{SettingsViewModel(locator.settingsStore,locator.backupRepository)});val lock by vm.appLockType.collectAsState(initial=AppLockType.NONE);val ai by vm.aiFeaturesEnabled.collectAsState(initial=false);val status by vm.exportStatus.collectAsState();val exported by vm.lastExportedFile.collectAsState();Scaffold(containerColor=MaterialTheme.colorScheme.background,topBar={TopAppBar(title={Text("Settings")})}){padding->Column(Modifier.fillMaxSize().padding(padding).verticalScroll(rememberScrollState()).padding(horizontal=20.dp,vertical=12.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){LifeOSSectionHeader("Privacy & security",supportingText="Control how LifeOS protects your private data");LifeOSCard{Column(Modifier.fillMaxWidth().padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){Row(verticalAlignment=Alignment.CenterVertically){LifeOSIconBadge(if(lock==AppLockType.NONE)Icons.Filled.LockOpen else Icons.Filled.Lock);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("App Lock",style=MaterialTheme.typography.titleLarge);Text(lockLabel(lock),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};Text("Choose None, PIN, or strong biometric protection. Your PIN and recovery answer are stored as salted hashes, not plaintext.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);Button(onClick=onOpenAppLockSetup,modifier=Modifier.fillMaxWidth()){Icon(Icons.Filled.Security,null);Spacer(Modifier.width(8.dp));Text(if(lock==AppLockType.NONE)"Set up App Lock" else "Change App Lock")}}};RemindersCard();LifeOSSectionHeader("Intelligence",supportingText="Everything runs locally on this device");LifeOSCard{Column(Modifier.fillMaxWidth().padding(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){LifeOSIconBadge(Icons.Filled.AutoAwesome);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("LifeOS Intelligence",style=MaterialTheme.typography.titleLarge);Text("Offline analysis and answers",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Switch(checked=ai,onCheckedChange=vm::setAiFeaturesEnabled)};Text("Diary, tasks, habits, trends, patterns and reports are analyzed locally. No external AI API or cloud service is required.",style=MaterialTheme.typography.bodySmall)}};LifeOSSectionHeader("Your data",supportingText="Export only when you choose to");LifeOSCard{Column(Modifier.fillMaxWidth().padding(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Backup & export",style=MaterialTheme.typography.titleLarge);Text("Create a JSON backup in app storage, then optionally share it using Android's share sheet.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={vm.exportBackup(context.filesDir)}){Icon(Icons.Filled.FileDownload,null);Spacer(Modifier.width(6.dp));Text("Export")};if(exported!=null)OutlinedButton(onClick={val uri=androidx.core.content.FileProvider.getUriForFile(context,"${context.packageName}.fileprovider",exported!!);val intent=android.content.Intent(android.content.Intent.ACTION_SEND).apply{type="application/json";putExtra(android.content.Intent.EXTRA_STREAM,uri);addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION)};context.startActivity(android.content.Intent.createChooser(intent,"Share LifeOS backup"))}){Text("Share")}};status?.let{Text(it,style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.primary)}}};Spacer(Modifier.height(24.dp))}}}
private fun lockLabel(lock:AppLockType)=when(lock){AppLockType.NONE->"Off · LifeOS opens immediately";AppLockType.BIOMETRIC->"Biometric · fingerprint/face verification";AppLockType.PIN->"PIN · separate LifeOS PIN protection"}
@Composable private fun RemindersCard(){val context=LocalContext.current;val permission=if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.TIRAMISU)rememberPermissionState(android.Manifest.permission.POST_NOTIFICATIONS)else null;val enabled=permission?.isGranted?:true;LifeOSCard{Column(Modifier.fillMaxWidth().padding(18.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Row(verticalAlignment=Alignment.CenterVertically){LifeOSIconBadge(Icons.Filled.Notifications);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("Reminders",style=MaterialTheme.typography.titleLarge);Text("Task and habit notifications",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Switch(checked=enabled,onCheckedChange={if(it){permission?.request?.invoke();NotificationHelper.ensureChannel(context)}})};Text("Permission is requested only when you turn reminders on.",style=MaterialTheme.typography.bodySmall)}}}
